const upsertAutomationRule = `-- name: UpsertAutomationRule :one

INSERT INTO automation_rules (
    workspace_id, rule_key, name, rule_type, version, is_enabled, config_json, created_by_user_id
) VALUES ($1, $2, $3, $4, 1, $5, $6, $7)
ON CONFLICT (workspace_id, rule_key) DO UPDATE
SET name = EXCLUDED.name,
    is_enabled = EXCLUDED.is_enabled,
    config_json = EXCLUDED.config_json,
    version = automation_rules.version + 1,
    updated_at = now()
RETURNING id, workspace_id, rule_key, name, rule_type, version, is_enabled, config_json, last_run_at, created_by_user_id, created_at, updated_at
`

